#!/bin/sh\n\nquotes=(\n  "When the world ends, make sure your coffee is still hot."\n  "The last sunrise is just another chance to reboot."\n  "Even in ruins, hope can be recycled."\n  "Survive the fallout, then throw a party."\n)\n\n# If QUOTE_INDEX is set, use it; otherwise pick a random index\nif [ -n "$QUOTE_INDEX" ]; then\n  idx=$QUOTE_INDEX\nelse\n  idx=$((RANDOM % ${#quotes[@]}))\nfi\n\n# Guard against out‑of‑range indices\nif [ "$idx" -ge "${#quotes[@]}" ] || [ "$idx" -lt 0 ]; then\n  idx=0\nfi\n\necho "${quotes[$idx]}"\n
